# PostGIS geography columns + GiST indexes (Phase 2 "Use PostGIS types for
# geospatial data"). Postgres-only: the ORM models stay portable lat/lon
# floats so SQLite tests never touch a PostGIS type (see
# docs/archive/BACKEND_V2_MIGRATION_ANALYSIS.md section 16.6).
_GEO_TABLES = ["incidents", "events", "shelters", "hospitals", "rescue_teams", "citizen_reports"]


def _add_postgis_columns() -> None:
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS postgis")
    for table in _GEO_TABLES:
        op.execute(f"ALTER TABLE {table} ADD COLUMN geom geography(Point, 4326)")
        op.execute(
            f"CREATE INDEX ix_{table}_geom ON {table} USING GIST (geom)"
        )
        op.execute(
            f"""
            CREATE OR REPLACE FUNCTION {table}_sync_geom() RETURNS trigger AS $$
            BEGIN
                IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN
                    NEW.geom := ST_SetSRID(ST_MakePoint(NEW.longitude, NEW.latitude), 4326);
                ELSE
                    NEW.geom := NULL;
                END IF;
                RETURN NEW;
            END;
            $$ LANGUAGE plpgsql
            """
        )
        op.execute(
            f"""
            CREATE TRIGGER {table}_sync_geom_trigger
            BEFORE INSERT OR UPDATE OF latitude, longitude ON {table}
            FOR EACH ROW EXECUTE FUNCTION {table}_sync_geom()
            """
        )


